pub fn openDir(self: NodeModulesFolder_, root: std.fs.Dir) !std.fs.Dir {
            if (comptime Environment.isPosix) {
                const p = try std.posix.toPosixPath(self.path.items);
                const fd = try bun.sys.openat(.fromStdDir(root), (&p), bun.O.DIRECTORY, 0).unwrap();
                return fd.stdDir();
            }
            return try bun.sys.openDirAtWindowsA(.fromStdDir(root), self.path.items, .{ .can_rename_or_delete = false, .read_only = false }).unwrap().stdDir();
    }

pub fn makeAndOpenDir(self: *NodeModulesFolder_, root: std.fs.Dir) !std.fs.Dir {
            const out = brk: {
            if (comptime Environment.isPosix) {
                break :brk try root.makeOpenPath(self.path.items, .{ .iterate = true, .access_sub_paths = true });
            }
            break :brk try bun.sys.openDirAtWindowsA(.fromStdDir(root), self.path.items, .{ .can_rename_or_delete = false, .op = .open_or_create, .read_only = false }).unwrap().stdDir();
};
            return out;
    }
};

pub const TreeContext_ = struct {
    pending_installs: std.ArrayListUnmanaged(DependencyInstallContext) = .{},
    binaries: Bin.PriorityQueue,
    install_count: usize = 0,

pub fn deinit(self: *TreeContext_, allocator: std.mem.Allocator) void {
            _ = self.pending_installs.deinit(allocator);
            _ = self.binaries.deinit();
    }
    pub const Id = Lockfile.Tree.Id;
};

pub const LazyNodeModulesPath_ = struct {
    node_modules: *NodeModulesFolder_,
    root_node_modules_dir: std.fs.Dir,
};

pub const LazyPackageDestinationDir_ = union(enum) {
    dir: std.fs.Dir,
    node_modules_path: LazyNodeModulesPath_,
    closed: void,

pub fn getDir(self: *LazyPackageDestinationDir_) !std.fs.Dir {
            return (switch (self.*) {
.dir => |dir| dir,
.node_modules_path => |lazy| brk: {
            const opened_dir = try lazy.node_modules.openDir(lazy.root_node_modules_dir);
            self.* = .{ .dir = opened_dir };
            break :brk opened_dir;
},
.closed => @panic("LazyPackageDestinationDir is closed! This should never happen. Why did this happen?! It's not your fault. Its our fault. We're sorry."),
});
    }

pub fn close(self: *LazyPackageDestinationDir_) void {
            switch (self.*) {
.dir => {
if ((self.dir.fd != std.fs.cwd().fd)) {
                _ = self.dir.close();
            }
},
.node_modules_path, .closed => {

},
}
            self.* = .closed;
    }
};

